<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {usePhasePage} from '../phasePage'
import {WorkforceApiError} from '../api'
import type {Employee} from '../types'
import type {LeaveBalancePage,LeaveBalance} from '../leaveEntitlements'
const {api,home,store,current,base,english,loading,busy,failure,notice,load}=usePhasePage(),en=computed(()=>english())
const employees=ref<Employee[]>([]),employee=ref(home.value?.myself?.id||''),year=ref(new Date().getFullYear()),data=ref<LeaveBalancePage|null>(null),type=ref(''),offset=ref(0)
const grant=ref('0'),carry=ref('0'),adjustment=ref('0'),unit=ref<'HOURS'|'DAYS'>('HOURS'),dayMinutes=ref<number|null>(null),reason=ref('')
const writableBalances=computed(()=>data.value?.balances.filter(b=>b.sourceStoreId===store.value&&!canonical(b))||[])
const balance=computed(()=>data.value?.balances.find(b=>b.typeId===type.value)),canManage=computed(()=>!!home.value?.employeeManage&&!!data.value?.canManage)
const pending=ref<{path:string;body:unknown}|null>(null)
function canonical(b:LeaveBalance){return b.unknownReasons.includes('CANONICAL_LEAVE_ACCOUNT')}
function display(n:number|null|undefined){return n==null?(en.value?'Unknown':'未知'):String(n)}
function selectPolicy(){const p=balance.value?.policy;grant.value=String(p?.grant??0);carry.value=String(p?.carryIn??0);adjustment.value=String(p?.adjustment??0);unit.value=p?.unit||'HOURS';dayMinutes.value=p?.dayMinutes??null;reason.value=p?.reason||''}
function refresh(){if(pending.value)return;data.value=null;void load(()=>api().get<LeaveBalancePage>(`/leave-entitlements?year=${year.value}${employee.value?'&employeeId='+encodeURIComponent(employee.value):''}`),v=>{data.value=v;employee.value=v.employeeId;if(!writableBalances.value.some(b=>b.typeId===type.value))type.value=writableBalances.value[0]?.typeId||'';selectPolicy()})}
async function listEmployees(){await load(()=>api().get<{items:Employee[]}>(`/employees?limit=50&offset=${offset.value}`),v=>{employees.value=v.items;if(!employee.value)employee.value=v.items[0]?.id||''});if(employee.value)refresh()}
function pageEmployees(delta:number){offset.value=Math.max(0,offset.value+delta);employee.value='';void listEmployees()}
function validDecimal(v:string,nonnegative:boolean){return /^-?\d{1,12}(\.\d{1,6})?$/.test(v)&&(!nonnegative||Number(v)>=0)}
function save(){if(data.value?.year!==year.value){failure.value=en.value?'Query the selected year again before saving':'请先重新查询所选年度再保存';return}const b=balance.value;if(!canManage.value||!b||b.sourceStoreId!==store.value||canonical(b)||pending.value)return;if(!validDecimal(grant.value,true)||!validDecimal(carry.value,true)||!validDecimal(adjustment.value,false)||!reason.value.trim()||(unit.value==='DAYS'&&(!Number.isInteger(dayMinutes.value)||Number(dayMinutes.value)<1||Number(dayMinutes.value)>1440))){failure.value=en.value?'Check amounts, reason and explicit minutes per day':'请检查额度、原因和每天天数折算分钟';return}pending.value={path:`/employees/${encodeURIComponent(employee.value)}/leave-entitlements/${crypto.randomUUID()}`,body:{expectedVersion:b.policy?.version||0,companyId:b.companyId,typeId:b.typeId,year:data.value.year,grant:grant.value,carryIn:carry.value,adjustment:adjustment.value,unit:unit.value,dayMinutes:unit.value==='DAYS'?dayMinutes.value:null,reason:reason.value}};void send()}
async function send(){if(!pending.value||busy.value)return;busy.value=true;failure.value='';const shop=store.value;try{await api().put(pending.value.path,pending.value.body);if(!current()||shop!==store.value)return;pending.value=null;notice.value=en.value?'Saved':'已保存';refresh()}catch(e){if(current()&&shop===store.value){if(e instanceof WorkforceApiError&&e.status<500)pending.value=null;failure.value=en.value?'Save failed. Retry the original request; reload after a conflict.':'保存失败。可重试原请求；版本冲突后请重新查询。'}}finally{if(current()&&shop===store.value)busy.value=false}}
watch(type,selectPolicy)
onMounted(()=>{if(home.value?.employeeManage)void listEmployees();else refresh()})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{en?'Yearly leave balance':'年度假期余额'}}</h2><RouterLink :to="base+'/attendance'">{{en?'Attendance':'考勤月表'}}</RouterLink></header>
<p class="wf-hint">{{en?'Contract leave accounts take precedence and include encashments in the same balance. Manual yearly grants apply only without a contract account. Day conversion uses the recorded policy. A negative balance does not reject leave or change pay.':'合同假期账户优先，折现与休假使用同一余额；仅无合同账户时维护人工年度额度。天数按已登记政策折算；余额不足不自动拒假或改变工资。'}}</p>
<div class="wf-grid"><label v-if="home?.employeeManage">{{en?'Employee':'员工'}}<select v-model="employee" :disabled="busy||!!pending" @change="refresh"><option v-for="e in employees" :key="e.id" :value="e.id">{{e.employeeNo}} · {{e.name}}</option></select></label><label>{{en?'Year':'年度'}}<input v-model.number="year" type="number" min="1900" max="9998" :disabled="busy||!!pending"/></label><button :disabled="loading||busy||!!pending" @click="refresh">{{en?'Query / retry':'查询 / 重试'}}</button></div>
<div v-if="home?.employeeManage" class="wf-inline"><button :disabled="offset===0||loading||busy||!!pending" @click="pageEmployees(-50)">{{en?'Previous employees':'上一页员工'}}</button><button :disabled="employees.length<50||loading||busy||!!pending" @click="pageEmployees(50)">{{en?'Next employees':'下一页员工'}}</button></div>
<p v-if="loading" role="status">{{en?'Loading…':'加载中…'}}</p><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="notice" role="status">{{notice}}</p>
<div v-if="data" class="wf-table-wrap"><table><thead><tr><th>{{en?'Leave type':'假别'}}</th><th>{{en?'Unit':'单位'}}</th><th>{{en?'Allowance':'年度额度'}}</th><th>{{en?'Used':'已用'}}</th><th>{{en?'Reserved':'待审预占'}}</th><th>{{en?'Remaining':'剩余'}}</th></tr></thead><tbody><tr v-for="b in data.balances" :key="b.typeId"><td>{{b.typeName}}<small v-if="canonical(b)"> · {{en?'Contract leave account; maintain the contract account. Manual yearly grants are unavailable.':'合同假期账户；请在合同假期账户维护，不可重复人工授额。'}}</small><small v-if="b.state==='UNKNOWN'"> · {{en?'Policy or measurement unavailable':'政策或计量资料不完整'}}</small></td><td>{{(b.accountUnit||b.policy?.unit)==='HOURS'?(en?'Hours':'小时'):(b.accountUnit||b.policy?.unit)==='DAYS'?(en?'Days':'天'):'—'}}</td><td>{{display(b.policy?.grant)}}</td><td>{{display(b.used)}}</td><td>{{display(b.reserved)}}</td><td>{{display(b.remaining)}}</td></tr><tr v-if="!data.balances.length"><td colspan="6">{{en?'No leave types configured':'尚未配置假别'}}</td></tr></tbody></table></div>
<form v-if="canManage&&writableBalances.length" class="wf-grid" @submit.prevent="save"><label>{{en?'Leave type':'假别'}}<select v-model="type" :disabled="busy||!!pending"><option v-for="b in writableBalances" :key="b.typeId" :value="b.typeId">{{b.typeName}}</option></select></label><label>{{en?'Annual grant':'年度额度'}}<input v-model="grant" inputmode="decimal" required :disabled="busy||!!pending"/></label><label>{{en?'Carry-in':'明确结转'}}<input v-model="carry" inputmode="decimal" required :disabled="busy||!!pending"/></label><label>{{en?'Adjustment (+/-)':'调整（正负）'}}<input v-model="adjustment" inputmode="decimal" required :disabled="busy||!!pending"/></label><label>{{en?'Unit':'单位'}}<select v-model="unit" :disabled="busy||!!pending"><option value="HOURS">{{en?'Hours':'小时'}}</option><option value="DAYS">{{en?'Days':'天'}}</option></select></label><label v-if="unit==='DAYS'">{{en?'Minutes per day (explicit)':'每天折算分钟（明确登记）'}}<input v-model.number="dayMinutes" type="number" min="1" max="1440" required :disabled="busy||!!pending"/></label><label>{{en?'Reason / grant source':'原因 / 额度来源'}}<textarea v-model="reason" required maxlength="500" :disabled="busy||!!pending"/></label><div class="wf-form-actions"><button type="submit" :disabled="busy||loading||!!pending">{{en?'Save yearly policy':'保存年度政策'}}</button></div></form>
<button v-if="pending" :disabled="busy" @click="send">{{en?'Retry save':'重试保存'}}</button>
<p class="wf-hint">{{en?'Approved leave and pending cancellation remain used; pending leave reserves allowance. Contract account totals also include encashments. Missing mappings or measurement remain unknown; leave types are never matched by name.':'已批假及销假待审仍计已用；待审预占，拒绝、撤回和完成销假释放。合同账户合计包含折现；缺失映射或计量仍为未知，不按假别同名猜测匹配。'}}</p>
</section></template>
